{"path": "robot_name.py", "content": "import random
import string


class Robot:
    _used_names = set()
    _rng = random.SystemRandom()

    def __init__(self):
        self.name = None
        self._assign_name()

    @classmethod
    def _generate(cls):
        if len(cls._used_names) >= 26 * 26 * 1000:
            raise RuntimeError("No robot names left")
        while True:
            name = "".join(cls._rng.choices(string.ascii_uppercase, k=2)) + \
                "".join(cls._rng.choices(string.digits, k=3))
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def _assign_name(self):
        self.name = self._generate()

    def reset(self):
        old = self.name
        self._assign_name()
        if old is not None:
            Robot._used_names.discard(old)
